entries[157845] = { ["name"] = "Falknerpfeife", ["text"] = "Questgegenstand\nBenutzen: Ruft Wilhelm, damit er bei der Vernichtung der Weidentalismane hilft." }
entries[157846] = { ["name"] = "Tasche mit aromatischen Zwiebeln", ["text"] = "Questgegenstand\n\"Allein der Geruch reicht aus, um den Zirkel aufzuhalten.\"" }
entries[157847] = { ["name"] = "Feuerstock", ["text"] = "Questgegenstand\nBenutzen: Tötet Schreckenszeckenbeißer und zerstört ihre Nester in einem kegelförmigen Bereich vor dem Zaubernden.\n\"Achtung: Kann sich mitunter spontan entzünden.\"" }
entries[157849] = { ["name"] = "Stinkendes Fläschchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[157850] = { ["name"] = "Stinkende Probe", ["text"] = "Questgegenstand\n\"Ihr solltet das besser nicht probieren.\"" }
entries[157851] = { ["name"] = "Bienenpheromone", ["text"] = "Questgegenstand\nBenutzen: Lässt einen verärgerten Bienenschwarm die Zerfleischer am Zielstandort angreifen. (10 Sek. Abklingzeit)" }
entries[157853] = { ["name"] = "Schwarznesseltinte", ["text"] = "Questgegenstand" }
entries[157854] = { ["name"] = "Rolle des Tintensogs", ["text"] = "Questgegenstand\nBenutzen: Zieht eine glitschige Schwarznessel innerhalb von 20 Metern zum Zaubernden und sammelt ihre Tinte ein. (5 Sek. Abklingzeit)\n\"Diese Schriftrolle fühlt sich feucht an.\"" }
entries[157855] = { ["name"] = "Azeritsplitter", ["text"] = "Questgegenstand\n\"Dieser Stein vibriert vor Macht.\"" }
entries[157857] = { ["name"] = "Walters' Chemikerausrüstung", ["text"] = "Questgegenstand" }
entries[157858] = { ["name"] = "Schädelpfeife der Rastari", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stößt einen unheimlichen Kriegsschrei aus, der Verteidiger der Rastari innerhalb von 25 Metern ermutigt." }
entries[157859] = { ["name"] = "Totenglocke", ["text"] = "Questgegenstand\nBenutzen: Befreit die Seelen in der Totenglocke. (30 Sek. Abklingzeit)" }
entries[157860] = { ["name"] = "Dunkler Fellzopf", ["text"] = "Questgegenstand\nDieser Gegenstand startet eine Quest.\n\"Ein Band aus dunklem, geflochtenem Fell. Es scheint von einem sehr großen Wendigo zu stammen.\"" }
entries[157861] = { ["name"] = "Himmelsruferedelsteinspan", ["text"] = "Questgegenstand\nEinzigartig (40)\n\"Beim Halten dieses Gegenstandes fährt Euch ein leichter elektrischer Schlag durch die Finger.\"" }
entries[157862] = { ["name"] = "Himmelsruferedelsteinmatrix", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Benutzt 25 Himmelsruferedelsteinspäne, um einen Himmelsruferedelstein zu erschaffen.\n\"In dieses Gerät ist ein Sockel eingelassen.\"" }
entries[157863] = { ["name"] = "Zusammengefügter Himmelsruferedelstein", ["text"] = "Questgegenstand\n\"Blitze knistern tief im Inneren dieses Edelsteins.\"" }
entries[157864] = { ["name"] = "Glitzernder Saphir", ["text"] = "Questgegenstand\n\"Schimmert und glänzt selbst im schwächsten Licht.\"" }
entries[157865] = { ["name"] = "Sulthis' Stein", ["text"] = "Questgegenstand\nEinzigartig\n\"Fühlt sich glatt und kühl an.\"" }
entries[157866] = { ["name"] = "Invasionspläne", ["text"] = "Questgegenstand\n\"Die an Aufseher Zarjish gerichteten Befehle wurden von Königin Azshara unterzeichnet.\"\n<Zum Lesen rechtsklicken>" }
entries[157867] = { ["name"] = "Geistbrechergesang", ["text"] = "Questgegenstand\nBenutzen: Tragt den Geistbrechergesang vor, den Euch Zul gelehrt hat, um Gedankensklaven in der Nähe von den Effekten des Zuvembibräus zu befreien. (3 Sek. Abklingzeit)" }
entries[157870] = { ["name"] = "Terrorhorn der Zandalari", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer Terrorhorn der Zandalari oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Zandalari sind stolz darauf, als Erste alle der gefährlichsten Echsen auf Azeroth aufgezogen und ausgebildet zu haben.\"\nErfolg:\nVerbündete Völker: Zandalaritrolle" }
