entries[158063] = { ["name"] = "Wiederbeschaffte Axt", ["text"] = "Questgegenstand\n\"In das Holz wurde eine Reihe von Namen eingeätzt. Die älteren Namen wurden ausgekratzt und durch den jeweils darauffolgenden Namen ersetzt.\"" }
entries[158064] = { ["name"] = "Großer Talisman der Kontrolle", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Übernimmt die Kontrolle über einen Blutholzverwüster." }
entries[158065] = { ["name"] = "Nachricht an Schmiedemeister Heller", ["text"] = "Questgegenstand\n\"Priscilla scheint diese Nachricht weder unterschrieben noch versiegelt zu haben.\"" }
