entries[158068] = { ["name"] = "Schriftrolle des Gral", ["text"] = "Questgegenstand\n\"Der Text dieser Schriftrolle ist in einem uralten Trolldialekt verfasst und mithilfe eines besonderen Codes verschlüsselt. Man könnte ein Leben damit verbringen, ihn zu entschlüsseln.\"" }
entries[158071] = { ["name"] = "Ermächtigungstrank", ["text"] = "Questgegenstand\nBenutzen: Wirft Narez' Ermächtigungstrank, um Krag'was Champions zu befreien. (5 Sek. Abklingzeit)" }
entries[158072] = { ["name"] = "Azeritbestäubte Klinge", ["text"] = "Der Tiragardesund\nWird beim Aufheben gebunden\nEinzigartig\n\"Ein gewöhnliches Schwert, dessen Klinge mit Azeritstaub bedeckt ist. Es sollte einem einzigen, gewaltigen Schlag standhalten.\"" }
entries[158075] = { ["name"] = "Herz von Azeroth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nHals\n+186 Ausdauer\nErhöht Eure kritische Trefferwertung um + 200.\nErhöht Eure Tempowertung um + 200.\nErhöht Eure Meisterschaftswertung um + 200.\nAnlegen: Nutzt die Energie des rohen Azerits, um außergewöhnliche Rüstungsteile zu erwecken, die über latente Kräfte verfügen.\n60 ( 60)\n\"Ein lebendes Symbol der Hoffnung, von den Champions eines sterbenden Planeten getragen. Jedes ihrer Kinder wird das Schicksal von Azeroth teilen.\"" }
entries[158077] = { ["name"] = "Fabergé-Ei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man François beschwört.\nMit Rechtsklick François beschwören oder wieder freigeben.\n80 ( 80)" }
