entries[158176] = { ["name"] = "Intakte tortollanische Schriftrolle", ["text"] = "Questgegenstand\nEinzigartig (99)\n\"Obwohl diese Schriftrolle mehrere Flecken aufweist, ist sie immer noch brauchbar.\"" }
