entries[158178] = { ["name"] = "Zerfledderte tortollanische Schriftrolle", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Schriftrolle ist zu stark beschädigt, um noch von Nutzen zu sein. Außerdem ist sie voller Krogggalle, Dreck und anderer unaussprechlicher Substanzen... Igitt!\"\nVerkaufspreis:" }
entries[158179] = { ["name"] = "Trank des Kampfgeschicks", ["text"] = "Das Arathihochland\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt dem Trinkenden größere Konzentration im Kampf und erhöht seinen verursachten Schaden für 10 Min. um 50%." }
entries[158180] = { ["name"] = "Der Glasierer", ["text"] = "Wird beim Anlegen gebunden\nEinhändig Streitkolben\n8 - 10 Schaden Geschwindigkeit 2.60\n(3.5 Schaden pro Sekunde)\n+3 Beweglichkeit\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
