entries[158201] = { ["name"] = "Kriegsrolle der Intelligenz", ["text"] = "Benutzen: Erhöht die Intelligenz des Ziels 30 Min. lang um 3%.\n\nWenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, erhalten alle Mitglieder den Effekt. Kann über Stufe 50 nicht eingesetzt werden.\nVerkaufspreis:" }
