entries[158212] = { ["name"] = "Zielfernrohr des Ausgucks", ["text"] = "Benutzen: Bringt dauerhaft ein Zielfernrohr an einer Distanzwaffe an, sodass manchmal Euer kritischer Trefferwert 12 Sek. lang um 194 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen dieser Vorrichtung an eine Distanzwaffe wird diese seelengebunden.\nVerkaufspreis:" }
