entries[158367] = { ["name"] = "Merekthas Fangzahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\nBenutzen: Drückt auf die Giftdrüse des Giftzahns und versprüht in einem kegelförmigen Bereich vor Euch einen giftigen Nebel. Der Nebel verursacht im Verlauf von 3 Sek. alle 1 Sek. 11 Naturschaden. Dieser Effekt ist bis zu 3-mal stapelbar. (2 Min Abklingzeit)\nVerkaufspreis:" }
