entries[158373] = { ["name"] = "Surrender Kristallkrummsäbel", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n6 - 12 Schaden Geschwindigkeit 2.60\n(3.5 Schaden pro Sekunde)\n+3 Stärke\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[158374] = { ["name"] = "Winziger Elektromentar im Glas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\nAnlegen: Eure Angriffe und Fähigkeiten haben eine Chance, 'Phänomenale Macht' zu gewähren. Beim Erreichen von 12 Stapeln setzt Ihr 'Blitz entfesseln' ein und verursacht 47 Naturschaden.\n\"Phänomenale Blitzkraft auf klitzekleinem Raum.\"\nVerkaufspreis:" }
entries[158375] = { ["name"] = "Tuch des treuen Vasallen", ["text"] = "Wird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nVerkaufspreis:" }
entries[158377] = { ["name"] = "Frostversetzte Munition", ["text"] = "Benutzen: Wertet dauerhaft die Munition einer Distanzwaffe auf, sodass Euer Ziel manchmal geringen Frostschaden erleidet und seine Bewegungsgeschwindigkeit für 3 Sek. um 20% verringert wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen dieser Vorrichtung an einer Distanzwaffe wird diese seelengebunden.\nVerkaufspreis:" }
entries[158378] = { ["name"] = "Bestickter Tiefseesatin", ["text"] = "Handwerksmaterial\n\"Wird von Spielercharakteren erstellt, die den Beruf Schneiderei ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[158379] = { ["name"] = "Instabiler temporaler Zeitverschieber", ["text"] = "Benutzen: Kehrt um ein kürzlich verstorbenes Ziel den Fluss der Zeit um und lässt es mit 60% Gesundheit sowie 20% Mana ins Leben zurückkehren. Kann im Kampf eingesetzt werden.\n\nEs besteht eine Chance auf eine Fehlzündung, die den Fluss der Zeit um ein Ziel beschleunigt und somit zu einem Verlust von Vitalität führt.\n\nKann nicht von Spielercharakteren über Stufe 50 eingesetzt werden. (10 Min Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (85)\n\"Dieses Gerät kann zwar die Toten ins Leben zurückrufen, versetzt aber unter Umständen auch die Lebenden an die Schwelle des Todes.\"" }
entries[158380] = { ["name"] = "Dämpfer magischer Störungen", ["text"] = "Benutzen: Macht Euch immun gegen manche Ärgernisse. Bleibt über den Tod hinaus bestehen. Hält 12 Stunden lang an.\n\"Ärgernisse schließen 'Glaubenssprung', Fähigkeiten zur Bedrohungsumleitung und manche Gerätschaften wie den Wechselblaster ein.\"\nVerkaufspreis:" }
